def press(obj, prefix=""):
    out = {}
    if isinstance(obj, dict):
        for k, v in obj.items(): out.update(press(v, prefix + k + "."))
    else: out[prefix[:-1]] = type(obj).__name__
    return out
print(press({"author": {"name": "JAH"}}))
assert press({"a": {"b": 1}}) == {"a.b": "int"}

from collections import deque
doors = {"hall": ["a", "b"], "a": ["c"], "b": [], "c": []}
lit, q, order = {"hall"}, deque(["hall"]), []
while q:
    room = q.popleft(); order.append(room)
    for nxt in doors[room]:
        if nxt not in lit: lit.add(nxt); q.append(nxt)
print("lit in order:", order)
assert order == ["hall", "a", "b", "c"]

crier = {"roll": ["east", "west"], "east": ["e1"], "west": ["w1", "w2"]}
streets = []
def listen(post):
    for s in crier.get(post, []):
        listen(s) if s in crier else streets.append(s)
listen("roll")
print("crier declares:", streets)
assert streets == ["e1", "w1", "w2"]

stairs = {"door": 0, "wing-a/1": 1, "wing-a/2": 3, "wing-b/1": 5}
deep = {u: d for u, d in stairs.items() if d >= 4}
print("chambers needing staircases:", deep)
assert deep == {"wing-b/1": 5}

expected = {"s1", "s2", "s3", "s4"}
gathered = {"s1", "s3"}
missing = sorted(expected - gathered)
print("missing sheaves:", missing)
assert missing == ["s2", "s4"]

sky = {"home": ["a"], "a": ["b"], "b": []}
for star, points in sky.items():
    print(f"{star} -> {', '.join(points) or '(none)'}")
assert len(sky) == 3

plate_old = {("home", "a")}
plate_new = {("home", "a"), ("home", "b")}
born, fallen = plate_new - plate_old, plate_old - plate_new
print("born:", born, "| fallen:", fallen)
assert born == {("home", "b")}

old = {"u1": "short"}
new = {"u1": "a much longer tale", "u2": "new arrival"}
arrived = [u for u in new if u not in old]
altered = [u for u in old if u in new and old[u] != new[u]]
print("arrived:", arrived, "| altered:", altered)
assert (arrived, altered) == (["u2"], ["u1"])
